// Ports the order pictograms (D-66, RS-007) into the UI: reads the signed-off SVGs that
// devloop/instances/world-conflict/runs/iter-03/concepts/order-icons/build.mjs generates and
// writes ui/src/components/orders/pictogramData.ts (one entry per registry id plus the 3
// reserve Economy icons). Redraw workflow (D-75): edit build.mjs, run it, then run this script.
// Run from the repo root: node ui/scripts/build-order-pictograms.mjs
// `tests/ui-order-pictograms.spec.ts` fails when the generated file and the SVGs drift apart.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
export const SRC = path.join(root, 'devloop/instances/world-conflict/runs/iter-03/concepts/order-icons');
export const OUT = path.join(root, 'ui/src/components/orders/pictogramData.ts');

/** One SVG file to its entry: the family, the label and the inner markup without the title. */
export function parseSvg(text) {
  const open = text.match(/<svg\b[^>]*>/);
  if (!open) throw new Error('no <svg> element');
  const attr = (n) => open[0].match(new RegExp(`${n}="([^"]*)"`))?.[1] ?? '';
  const body = text
    .slice(open.index + open[0].length, text.lastIndexOf('</svg>'))
    .replace(/<title>[\s\S]*?<\/title>/, '')
    .trim();
  return { id: attr('data-order-id'), family: attr('data-family'), label: attr('aria-label'), body };
}

export function buildSource() {
  const files = fs.readdirSync(SRC).filter((f) => f.endsWith('.svg')).sort();
  const entries = files.map((f) => parseSvg(fs.readFileSync(path.join(SRC, f), 'utf8')));
  const lines = entries.map(
    (e) => `  ${JSON.stringify(e.id)}: { family: ${JSON.stringify(e.family)}, label: ${JSON.stringify(e.label)}, body: ${JSON.stringify(e.body)} },`,
  );
  return `// Generated by ui/scripts/build-order-pictograms.mjs from
// devloop/instances/world-conflict/runs/iter-03/concepts/order-icons/*.svg. Do not edit by hand:
// redraw in build.mjs, run it, then run the script (D-75).
export interface PictogramSource {
  /** The family the icon was drawn for (diplo, mil, nuke, intel, econ, home). */
  family: string;
  /** The order's name, used as the accessible name when the card gives none. */
  label: string;
  /** Inner SVG markup on a 48 x 48 grid; mask and clipPath ids start with \`oi-\`. */
  body: string;
}

export const PICTOGRAM_SOURCE: Record<string, PictogramSource> = {
${lines.join('\n')}
};
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  fs.writeFileSync(OUT, buildSource());
  console.log(`wrote ${path.relative(root, OUT)}`);
}
